INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c14-7cd2-b241-27a307a25f99'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'F is inversely proportional to the square of d. Explain what happens to F when d is halved.', 'F becomes 4 times the original value.', 'Since F is inversely proportional to d^2, halving d makes d^2 become one quarter of the original value. Therefore F becomes 4 times as large.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.564Z'::timestamptz, '2026-08-15T07:36:12.564Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c28-7a53-b1de-56308e632bf5'::uuid, '019f9df7-a2a2-7899-9f80-1aed5da88c11'::uuid, 'In a cake recipe problem, a matrix product AB is used to combine ingredient amounts with the number of cakes baked. Explain what the entries of AB represent.', 'They represent the total amounts of each ingredient required.', 'When a matrix of ingredient quantities per cake is multiplied by a matrix showing how many cakes are made, each entry in the product gives the total amount of a particular ingredient needed.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.584Z'::timestamptz, '2026-08-15T07:36:12.584Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00459-8c3c-7f99-a598-2738e3fd3e42'::uuid, '019f9df7-a2a2-7839-8287-1e75e9dd37f8'::uuid, 'Express 10 000 SGD in USD if the exchange rate is USD 1 = SGD x.', '10000/x', 'If 1 USD = x SGD, then the number of USD received for 10 000 SGD is 10 000 divided by x.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:36:12.604Z'::timestamptz, '2026-08-15T07:36:12.604Z'::timestamptz) ON CONFLICT (id) DO NOTHING;